// Shared SVG coordinates. The frame and brand path constants above are unchanged.
export const BRICK_LAYOUT = Object.freeze({
  width: BRICK_WIDTH, height: BRICK_HEIGHT,
  right: 4455, textWidth: 3850, titleBaseline: 752, nameBaseline: 1218,
  fontFamily: "Roboto", fontWeight: 300, fontSize: 440, tracking: 60,
  // Bundled Roboto Light hhea metrics: 1900 / -500, 2048 units per em.
  ascent: 1900 / 2048, descent: 500 / 2048,
  clip: { x: 180, y: 180, width: 4640, height: 1270, radius: 100 },
});
const escapeXml = (value: string) => value.replace(/[&<>"']/g, char => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&apos;" }[char]!));
export function brickTextScale(value: string): number {
  const width = Array.from(value).reduce((sum, char) => sum + ((glyphWidths as Record<string, number>)[char] ?? 440) + BRICK_LAYOUT.tracking, 0);
  return Math.min(1, BRICK_LAYOUT.textWidth / Math.max(width, 1));
}
export function brickTextLine(value: string, y: number): string {
  return `<g transform="translate(4455 ${y}) scale(${brickTextScale(value)} 1)"><text x="0" y="0" text-anchor="end" font-family="Roboto" font-weight="300" font-size="440" letter-spacing="60">${escapeXml(value)}</text></g>`;
}
// Split the original, unmodified brand paths into their two canonical lines.
const logoPaths = LOGO_LETTERS.match(/<path\b[^>]*\/>/g) || [];
export const BRAND_TITLE_PATHS = `<g fill="#fff">${logoPaths.slice(0, 7).join("")}</g>`;
export const BRAND_NAME_PATHS = `<g fill="#fff">${logoPaths.slice(7).join("")}</g>`;
export function brickLetters(title: string, name: string): string {
  return title === "Grandma" && name === "Jazz" ? LOGO_LETTERS : `<g fill="#fff">${brickTextLine(title, BRICK_LAYOUT.titleBaseline)}${brickTextLine(name, BRICK_LAYOUT.nameBaseline)}</g>`;
}
export function brickSvg(title: string, name: string, frameUrl?: string): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 5000 1630" width="5000" height="1630" role="img" aria-label="${escapeXml(`${title} ${name}`)}">${frameUrl ? `<image href="${escapeXml(frameUrl)}" width="5000" height="1630" />` : BRICK_FRAME}${brickLetters(title, name)}</svg>`;
}
